 start(){if(this.s.mode==='combat')return false;if(this.s.deadUntil>0)return this.fail('仍在死亡休整。');if(this.s.hp<this.stats().hp*.1)return this.fail('生命过低，请先在营地恢复。');this.s.mode='exploring';this.s.resume=true;this.emit('队伍出发：'+REGIONS[this.s.region].name+'。','system');return true;}
