 const chance=this.lootChance(e.kind,st);if(this.random()<chance.material){let pool=r.pool;if(e.kind==='elite'&&this.random()<.18&&r.id<15)pool=REGIONS[r.id+1].pool;const id=pool[Math.floor(this.random()*pool.length)],amount=e.kind==='boss'?6:e.rare?2:1;s.materials[id]+=amount;this.emit('获得 '+MATERIALS.find(m=>m.id===id).name+' ×'+amount+'。','loot',{kind:'drop',type:'material',label:MATERIALS.find(m=>m.id===id).name+' ×'+amount});}
