 makeItem(region,kind='normal',forcedSlot=null){const slots=Object.keys(SLOTS),slot=forcedSlot||slots[Math.floor(this.random()*slots.length)],q=this.random(),quality=kind==='boss'?(q<.12?4:q<.55?3:2):kind==='elite'?(q<.015?4:q<.12?3:q<.5?2:1):(q<.01?3:q<.1?2:q<.4?1:0),base=SLOTS[slot],factor=REGIONS[region].scale*QUALITY_MULT[quality]*(.9+this.random()*.2),stats={[base.primary]:Math.round(base.base*factor)};
 const count=quality===0?0:quality===1?1:quality===2?2:3,pool=['hp','attack','defense','insight','speed','greed','intimidation','leadership','lifesteal'].filter(k=>k!==base.primary);for(let n=0;n<count&&pool.length;n++){const index=Math.floor(this.random()*pool.length),key=pool.splice(index,1)[0];stats[key]=key==='lifesteal'?Math.round((.2+quality*.25+region*.035)*10)/10:['greed','intimidation','leadership','speed','insight'].includes(key)?Math.round((1+region*.7)*QUALITY_MULT[quality]):Math.round((key==='hp'?15:2)*factor);}
 return {id:'g'+this.s.serial++,name:REGIONS[region].name.slice(0,2)+({head:'战盔',shoulder:'肩甲',bracer:'护腕',mainhand:'长剑',offhand:'短刃',gloves:'手套',chest:'胸甲',belt:'腰带',legs:'护腿',boots:'战靴',charm:'挂饰',ring:'戒指',mask:'面具'}[slot]),slot,region,quality,stats};}
 itemScore(item){const w={hp:.14,attack:2,defense:2,insight:1,speed:1,greed:2,intimidation:2,leadership:2,lifesteal:12};return Object.entries(item.stats).reduce((sum,[k,v])=>sum+v*(w[k]||1),0);}
 salePrice(i){return Math.round((12+this.itemScore(i)*2)*1.25**i.region);}
 receiveItem(item){const s=this.s;s.dropCount++;if(s.autoEquip&&this.itemScore(item)>this.itemScore(s.equipped[item.slot]||{stats:{}})){const old=s.equipped[item.slot];s.equipped[item.slot]=item;if(old)s.bag.push(old);s.hp=Math.min(s.hp,this.stats().hp);}else s.bag.push(item);while(s.bag.length>this.bagCap()){if(s.autoSell){const old=s.bag.shift();s.gold+=this.salePrice(old);}else{s.bag.pop();this.emit('行囊已满，新装备被遗留；可扩建仓库或开启满包出售。','system');break;}}this.emit('获得 '+QUALITY[item.quality]+' '+item.name+'。','loot',{kind:'drop',type:'equipment',label:QUALITY[item.quality]+' · '+item.name,quality:item.quality});return item;}
 equip(id){const n=this.s.bag.findIndex(i=>i.id===id);if(n<0)return false;const item=this.s.bag.splice(n,1)[0],old=this.s.equipped[item.slot];this.s.equipped[item.slot]=item;if(old)this.s.bag.push(old);this.s.hp=Math.min(this.s.hp,this.stats().hp);return true;}
 sellItem(id){const n=this.s.bag.findIndex(i=>i.id===id);if(n<0)return false;this.s.gold+=this.salePrice(this.s.bag.splice(n,1)[0]);return true;}
 salvage(id){if(!this.lv('academy'))return this.fail('请先建造研习所。');const n=this.s.bag.findIndex(i=>i.id===id);if(n<0)return false;const item=this.s.bag.splice(n,1)[0],r=REGIONS[item.region];this.s.materials[r.pool[0]]+=1+item.quality;return true;}
 hireCost(id,count=1){const t=TROOPS.find(t=>t.id===id);if(!t||!Number.isInteger(count)||count<1)return Infinity;let cost=0;for(let n=0;n<count;n++)cost+=t.price*1.003**(this.troopCount()+n);return Math.ceil(cost);}
 hire(id,count=1){if(this.troopCount()+count>this.troopCap())return this.fail('佣兵容量不足，升级兵营。');const cost=this.hireCost(id,count);if(!Number.isFinite(cost)||this.s.gold<cost)return this.fail('金币不足。');this.s.gold-=cost;this.s.troops[id]+=count;this.emit('雇佣 '+count+' 名'+TROOPS.find(t=>t.id===id).name+'。','system');return true;}
 trainingCost(type){return Math.round((type==='troop'?120:90)*1.30**this.s.training[type]);}
