 buildingCost(b){const lv=this.lv(b.id),tier=Math.min(15,Math.max(0,lv-1)),r=REGIONS[tier],cost={gold:Math.round(b.cost*1.9**lv)};for(const id of r.pool)cost[id]=Math.ceil(b.mat*(1+lv*.7));if(b.id==='altar')cost.seal=1;return cost;}
