 facilityCap(b){return Math.min(b.max,['barracks','beastpen'].includes(b.id)?this.lv('hall')+Math.ceil(this.lv('hall')/2):this.lv('hall')+1);}
 canBuild(b){return this.lv(b.id)<b.max&&(b.id!=='hall'||this.lv('hall')<3||this.s.cleared.filter(Boolean).length>=this.lv('hall')-2)&&this.lv('hall')>=b.requires&&(b.id==='hall'||this.lv(b.id)<this.facilityCap(b))&&this.canPay(this.buildingCost(b));}
 build(id){const b=BUILDINGS.find(b=>b.id===id);if(!b||!this.canBuild(b))return false;this.pay(this.buildingCost(b));this.s.camp[id]++;this.emit(b.name+' 升至 Lv.'+this.lv(id)+'。','system');return true;}
 enhanceCost(slot){const rank=this.s.ranks[slot]||0,r=REGIONS[Math.min(15,Math.floor(rank/5))];return {gold:Math.round(65*1.25**rank),[r.pool[0]]:3+Math.floor(rank/2)};}
 enhance(slot){if(!SLOTS[slot]||!this.lv('workshop')||(this.s.ranks[slot]||0)>=this.lv('workshop')*5)return false;if(!this.pay(this.enhanceCost(slot)))return false;this.s.ranks[slot]++;return true;}
 craftCost(region){const r=REGIONS[region],cost={gold:Math.round(100*1.8**region)};r.pool.forEach(id=>cost[id]=12+region*2);return cost;}
