 useSpecial(id){if(!this.s.special[id])return false;if(id==='potion'){if(this.s.deadUntil>0||this.s.hp>=this.stats().hp)return false;this.s.hp=Math.min(this.stats().hp,this.s.hp+this.stats().hp*.35);}else if(id==='scroll')this.s.bonusInsight+=2;else return false;this.s.special[id]--;return true;}
